/**
 * SLF Portal — bulk upload pipeline, driven by the ACTUAL developer test
 * workbooks in docs/dev-test-data (generated by
 * server/scripts/generateDevTestWorkbook.js).
 *
 * Everything from the spreadsheet bytes up to the API boundary is the real
 * code path: XLSX parsing, the portal's header→field mapping, the required
 * column/row validators, the hauler↔client relationship check, and the merge
 * that `handleConfirmUpload` performs into the existing Accredited Haulers.
 *
 * The only mirrored piece is the field-mapping loop, which lives inline in
 * index.jsx#handleExcelUpload and cannot be imported; it is reproduced verbatim
 * below and pinned by the header assertions.
 *
 * Run: npm test  (from front-end/)
 */
import test from "node:test";
import assert from "node:assert/strict";
import path from "node:path";
import { readFileSync, existsSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import * as XLSX from "xlsx";

import {
  UPLOAD_COLUMNS,
  getUploadMissingColumns,
  getUploadRowErrors,
  getUploadRelationshipErrors,
  findUploadHauler,
  findUploadClientForHauler,
  uploadHeaderKey,
  cleanUploadText,
  parseUploadNumber,
  isEmptyUploadValue,
  isNumberOfTrucksHeader,
  isHaulerNameHeader,
  isClientsHeader,
} from "../uploadHelpers.js";
import { mergeHaulersByName } from "../haulerNormalization.js";
import { normalizeUnit } from "../helpers.js";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(HERE, "..", "..", "..", "..", "..", "docs", "dev-test-data");
const UNIT = "m³";

// The demo facility's open cells (seeds/seedDemoAccounts.js): Cell 1 is
// Used/Completed and Cell 5 is Under Construction, so neither is selectable.
const ACTIVE_CELL_OPTIONS = [
  { value: "Cell 2", cellName: "Cell 2", label: "Cell 2 - Residual", cellIndex: 1, cellType: "Residual" },
  { value: "Cell 3", cellName: "Cell 3", label: "Cell 3 - Residual", cellIndex: 2, cellType: "Residual" },
  { value: "Cell 4", cellName: "Cell 4", label: "Cell 4 - Treated Haz Waste", cellIndex: 3, cellType: "Treated Haz Waste" },
];

// The workbooks are GENERATED artifacts (server/scripts/generateDevTestWorkbook.js),
// not committed binaries, so build them on demand if they are missing. Keeps the
// suite runnable on a fresh clone and after any checkout that removed them.
if (!existsSync(path.join(DATA_DIR, "01_Hauler_Bulk_Upload.xlsx"))) {
  execFileSync(
    process.execPath,
    [path.join(HERE, "..", "..", "..", "..", "..", "server", "scripts", "generateDevTestWorkbook.js")],
    { stdio: "ignore" },
  );
}

const readSheet = (file) => {
  // Same call the portal makes on the FileReader result, so parsing behaviour is
  // identical to a real upload.
  const wb = XLSX.read(readFileSync(path.join(DATA_DIR, file)), { type: "buffer" });
  const ws = wb.Sheets[wb.SheetNames[0]]; // the portal reads sheet 1 only
  return XLSX.utils
    .sheet_to_json(ws, { defval: "" })
    .filter((row) => Object.values(row || {}).some((v) => cleanUploadText(v) !== ""));
};

const resolveUploadCell = (value) => {
  const comparable = cleanUploadText(value).toLowerCase();
  const match = ACTIVE_CELL_OPTIONS.find((o) =>
    [o.value, o.cellName, o.label]
      .filter(Boolean)
      .map((c) => cleanUploadText(c).toLowerCase())
      .includes(comparable),
  );
  return {
    cellName: match?.value || cleanUploadText(value),
    cellIndex: typeof match?.cellIndex === "number" ? match.cellIndex : null,
    cellType: match?.cellType || "",
  };
};

// ── Mirror of index.jsx#handleExcelUpload's normalization loop ───────────────
const normalizeRows = (rows, type, haulers = []) =>
  rows.map((row, i) => {
    const col = (field) => UPLOAD_COLUMNS[type].find((c) => c.field === field);
    const n = { key: `upload-${i}`, _rowNumber: i + 2 };
    for (const [rawKey, value] of Object.entries(row)) {
      const k = uploadHeaderKey(rawKey);
      if (type === "truck") {
        if (col("disposalDate")?.matches(k)) n.disposalDate = cleanUploadText(value);
        else if (col("disposalTicketNo")?.matches(k)) n.disposalTicketNo = cleanUploadText(value);
        else if (col("hauler")?.matches(k)) n.hauler = cleanUploadText(value);
        else if (col("client")?.matches(k)) n.client = cleanUploadText(value);
        else if (k.includes("plate")) n.plateNumber = cleanUploadText(value);
        else if (k.includes("capacity") && !k.includes("unit")) n.truckCapacity = parseUploadNumber(value);
        else if (col("actualVolume")?.matches(k)) n.actualVolume = parseUploadNumber(value);
        else if (col("actualVolumeUnit")?.matches(k)) n.actualVolumeUnit = normalizeUnit(value || UNIT);
        else if (col("cellName")?.matches(k)) Object.assign(n, resolveUploadCell(value));
        else if (k.includes("waste") && k.includes("type")) n.wasteType = cleanUploadText(value);
        else if (k.includes("haz") || k.includes("code"))
          n.hazWasteCode = cleanUploadText(value).split(",").map((s) => s.trim()).filter(Boolean);
      } else {
        if (isNumberOfTrucksHeader(k)) n.numberOfTrucks = parseUploadNumber(value);
        else if (isHaulerNameHeader(k)) n.haulerName = cleanUploadText(value);
        else if (k.includes("client") && k.includes("type")) n.clientType = cleanUploadText(value);
        else if (k.includes("client") && k.includes("address")) n.clientAddress = cleanUploadText(value);
        else if (isClientsHeader(k))
          n.privateSectorClients = cleanUploadText(value).split(",").map((s) => s.trim()).filter(Boolean);
        else if (k.includes("office") || k.includes("address")) n.officeAddress = cleanUploadText(value);
        else if (k.includes("plate")) n.plateNumber = cleanUploadText(value);
        else if (k.includes("vehicle") || k.includes("type")) n.vehicleType = cleanUploadText(value);
        else if (k.includes("capacity") && !k.includes("unit")) n.capacity = parseUploadNumber(value);
        else if (k.includes("capacity") && k.includes("unit")) n.capacityUnit = normalizeUnit(value || UNIT);
      }
    }
    const relationshipErrors = type === "truck" ? getUploadRelationshipErrors(n, haulers) : [];
    if (type === "truck" && relationshipErrors.length === 0) {
      const matchedHauler = findUploadHauler(haulers, n.hauler);
      const matchedClient = findUploadClientForHauler(matchedHauler, n.client);
      if (matchedClient && !matchedClient.ambiguous && !matchedClient.inactiveOnly) n._matchedClient = matchedClient;
    }
    const cellKnown = type !== "truck" || !n.cellName || n.cellIndex != null;
    return {
      ...n,
      _errors: [
        ...getUploadRowErrors(n, type),
        ...relationshipErrors,
        ...(cellKnown ? [] : [`Row ${n._rowNumber} — Cell or Disposal Area "${n.cellName}" is not an available cell under this SLF.`]),
      ],
    };
  });

// Mirror of index.jsx#handleConfirmUpload for uploadType "hauler".
const toHaulerRecords = (rows) =>
  rows.map((d) => ({
    key: d.key,
    haulerName: d.haulerName || "",
    numberOfTrucks: parseUploadNumber(d.numberOfTrucks),
    officeAddress: d.officeAddress || "",
    vehicles:
      d.plateNumber || d.vehicleType || !isEmptyUploadValue(d.capacity)
        ? [
            {
              plateNumber: d.plateNumber || "",
              vehicleType: d.vehicleType || "",
              capacity: parseUploadNumber(d.capacity),
              capacityUnit: d.capacityUnit || UNIT,
            },
          ]
        : [],
    privateSectorClients: (d.privateSectorClients || []).map((c, index) => ({
      key: `${d.key}-client-${index}`,
      clientName: c,
      clientType: d.clientType || "Private",
      clientAddress: d.clientAddress || "",
    })),
  }));

// ── T05a — hauler bulk upload ───────────────────────────────────────────────
test("T05 01_Hauler_Bulk_Upload imports cleanly and builds the baseline haulers", () => {
  const rows = readSheet("01_Hauler_Bulk_Upload.xlsx");
  assert.equal(rows.length, 3);
  assert.deepEqual(getUploadMissingColumns(Object.keys(rows[0]), "hauler"), []);

  const normalized = normalizeRows(rows, "hauler");
  assert.deepEqual(normalized.flatMap((r) => r._errors), [], "no row may be rejected");

  const haulers = mergeHaulersByName(toHaulerRecords(normalized), UNIT);
  assert.equal(haulers.length, 2, "TEST HAULER 001 (2 rows) + TEST HAULER 002");
  const h1 = haulers.find((h) => h.haulerName === "TEST HAULER 001");
  assert.equal(h1.vehicles.length, 2);
  assert.deepEqual(h1.vehicles.map((v) => v.capacity).sort((a, b) => a - b), [12, 15]);
  assert.equal(h1.privateSectorClients.length, 2);
  assert.equal(h1.privateSectorClients[0].clientAddress, "TEST CLIENT ADDRESS 001");
  assert.equal(h1.officeAddress, "TEST ADDRESS 001, Demonstration Valley");
});

// ── T06 — partial update must not erase the omitted columns ─────────────────
test("T06 02_Hauler_Partial_Update changes ONLY capacity and keeps every omitted field", () => {
  const baseline = mergeHaulersByName(
    toHaulerRecords(normalizeRows(readSheet("01_Hauler_Bulk_Upload.xlsx"), "hauler")),
    UNIT,
  );
  const partialRows = readSheet("02_Hauler_Partial_Update.xlsx");
  const partial = normalizeRows(partialRows, "hauler");
  assert.deepEqual(partial.flatMap((r) => r._errors), [], "a partial file must still validate");
  // The file genuinely omits these columns.
  for (const omitted of ["Office Address", "Vehicle Type", "Clients", "Client Address"]) {
    assert.equal(Object.keys(partialRows[0]).includes(omitted), false, `${omitted} must be absent`);
  }

  const merged = mergeHaulersByName([...baseline, ...toHaulerRecords(partial)], UNIT);
  const h1 = merged.find((h) => h.haulerName === "TEST HAULER 001");
  const tst1 = h1.vehicles.find((v) => v.plateNumber === "TST-0001");

  assert.equal(tst1.capacity, 18, "the uploaded capacity must apply (15 → 18)");
  assert.equal(tst1.vehicleType, "Dump Truck", "vehicle type was not uploaded — keep it");
  assert.equal(h1.officeAddress, "TEST ADDRESS 001, Demonstration Valley", "office address must survive");
  assert.equal(h1.vehicles.length, 2, "the untouched vehicle must remain");
  assert.equal(h1.vehicles.find((v) => v.plateNumber === "TST-0002").capacity, 12, "unrelated vehicle unchanged");
  assert.equal(h1.privateSectorClients.length, 2, "clients must survive a vehicle-only upload");
  assert.equal(h1.privateSectorClients[0].clientAddress, "TEST CLIENT ADDRESS 001");
  assert.equal(merged.find((h) => h.haulerName === "TEST HAULER 002").vehicles[0].capacity, 22);
});

// ── T05b / T08 — disposal bulk upload against that baseline ─────────────────
test("T05 03_Disposal_Bulk_Upload validates against the uploaded haulers/clients", () => {
  const haulers = mergeHaulersByName(
    toHaulerRecords(normalizeRows(readSheet("01_Hauler_Bulk_Upload.xlsx"), "hauler")),
    UNIT,
  );
  const rows = readSheet("03_Disposal_Bulk_Upload.xlsx");
  assert.equal(rows.length, 4);
  assert.deepEqual(getUploadMissingColumns(Object.keys(rows[0]), "truck"), []);

  const normalized = normalizeRows(rows, "truck", haulers);
  assert.deepEqual(
    normalized.flatMap((r) => r._errors),
    [],
    "valid disposal rows must not report duplicate/ambiguous or relationship errors",
  );
  // Every row resolved a real cell identifier and its client.
  assert.deepEqual(normalized.map((r) => r.cellIndex), [1, 1, 2, 3]);
  assert.deepEqual(normalized.map((r) => r.truckCapacity), [15, 12, 20, 20]);
  assert.equal(normalized.every((r) => r._matchedClient), true, "each row must bind its client");
  assert.deepEqual(normalized[3].hazWasteCode, ["K301"]);
});

// ── T05c — duplicate handling ───────────────────────────────────────────────
test("T05 05_Duplicate_Data_Test merges duplicates instead of failing as ambiguous", () => {
  const rows = readSheet("05_Duplicate_Data_Test.xlsx");
  assert.equal(rows.length, 3);
  const normalized = normalizeRows(rows, "hauler");
  assert.deepEqual(normalized.flatMap((r) => r._errors), []);

  const haulers = mergeHaulersByName(toHaulerRecords(normalized), UNIT);
  assert.equal(haulers.length, 1, "casing variants of one hauler are one hauler");
  assert.equal(haulers[0].privateSectorClients.length, 1, "the repeated client is one client");
  assert.equal(haulers[0].vehicles.length, 2, "TST-0001 merged; TST-0004 added");
  assert.equal(
    haulers[0].vehicles.find((v) => v.plateNumber === "TST-0001").vehicleType,
    "Dump Truck",
    "the blank duplicate row must not blank the stored vehicle type",
  );

  // The duplicated client must still resolve for a disposal row — this is the
  // exact lookup that used to report "duplicated or ambiguous" and block submit.
  const hauler = findUploadHauler(haulers, "TEST HAULER 001");
  const client = findUploadClientForHauler(hauler, "TEST CLIENT 001");
  assert.equal(client.ambiguous, undefined, "one client stored several ways is not ambiguous");
  assert.equal(client.clientName, "TEST CLIENT 001");
});

test("T05 a client stored in privateSectorClients AND on a vehicle is not ambiguous", () => {
  const hauler = {
    haulerName: "TEST HAULER 001",
    privateSectorClients: [{ clientName: "TEST CLIENT 001", clientType: "Private" }],
    clients: [{ clientName: "TEST CLIENT 001" }],
    vehicles: [{ plateNumber: "TST-0001", selectedClients: [{ clientName: "test client 001" }] }],
  };
  const client = findUploadClientForHauler(hauler, "TEST CLIENT 001");
  assert.equal(client.ambiguous, undefined);
  assert.equal(client.clientType, "Private", "the richest copy wins");
  assert.deepEqual(getUploadRelationshipErrors({ _rowNumber: 2, hauler: "TEST HAULER 001", client: "TEST CLIENT 001" }, [hauler]), []);
});

// ── T05d — invalid data is reported, never imported ────────────────────────
test("T05 04_Invalid_Data_Test rejects every seeded defect", () => {
  const haulers = mergeHaulersByName(
    toHaulerRecords(normalizeRows(readSheet("01_Hauler_Bulk_Upload.xlsx"), "hauler")),
    UNIT,
  );
  const rows = readSheet("04_Invalid_Data_Test.xlsx");
  assert.equal(rows.length, 8);
  const normalized = normalizeRows(rows, "truck", haulers);

  normalized.forEach((row, i) => {
    assert.ok(row._errors.length > 0, `invalid row ${i + 1} (${row.disposalTicketNo}) must be reported`);
  });
  const joined = normalized.map((r) => r._errors.join(" | "));
  assert.match(joined[0], /Disposal Date/);
  assert.match(joined[1], /Waste Volume must be greater than 0/);
  assert.match(joined[2], /Truck Capacity must be greater than 0/);
  assert.match(joined[3], /Waste Volume must be greater than 0/);
  assert.match(joined[4], /Hauler .* is not assigned under this SLF/);
  assert.match(joined[5], /Client .* is not assigned to hauler/);
  assert.match(joined[6], /is not an available cell under this SLF/);
  assert.match(joined[7], /Cell or Disposal Area/);

  // handleConfirmUpload refuses the whole import when any row carries an error.
  assert.equal(normalized.some((r) => r._errors.length), true);
});
